#include <stdint.h>
#include "main.h"



int main(void)
{
	RCC_AHB1ENR_t volatile *const pClockContrlReg = (RCC_AHB1ENR_t*) (0x40023800	+	0x30);
	GPIOx_MODER_t volatile *const pGPIOAmodeReg = (GPIOx_MODER_t*)(0x40020000	+ 0x00);
	GPIOx_ODR_t volatile *const pOPdataReg = (GPIOx_ODR_t*)(0x40020000	+	0x14);

	//	1. Enable the clock in peripheral A in RCC_AHB1ENR
		pClockContrlReg -> gpio_a_en = 1;

	//	2. Configure the mode as GPIOA pin as OUTPUT
		pGPIOAmodeReg -> moder5 = 1;


	while(1)
		{
		//	3. SET 5 bit of the output data register to make I/O pin-5 HIGH
				pOPdataReg -> odr5 = 1;
		//	Introducing the Human Observable Delay
			for(uint32_t volatile i = 0; i <= 1000000 ; i++);
		//	Turn off the LED
				pOPdataReg -> odr5 = 0;
		//	Again Introducing Delay
			for(uint32_t volatile i=0; i<= 100000 ; i++);
		}

}
